import { Image, PixelRatio, type ImageStyle, type StyleProp } from 'react-native';
import { BRAND_NAME } from '../theme/brand';

/**
 * The one logo of the app. Nothing else loads a brand image: the header, the middle button of the
 * bottom bar, the drawer, the inbox and the login screen all come through this component.
 *
 * The pictures are generated by `tools/brand/make-assets.mjs` from
 * `assets-src/jungle-book-logo.jpg`: the letters alone, on transparency. The dark green field of the
 * photograph is removed by the generator (and its numbers checked by `npm run test:brand-assets`),
 * so the mark needs no frame, no square, no circle and no background of its own â€” it sits on
 * whatever the screen already is.
 *
 * - `header` is the 52 dp mark of the top bar and of the inbox, exported at 1x/2x/3x;
 * - `nav` is the 54 dp mark inside the create cell, exported at 1x/2x/3x;
 * - `large` is the drawing of the login screen.
 *
 * The mark is drawn with no frame of its own: no square, no disc, no ring, no shadow and no colour
 * behind it (the owner's rule, 17 October 2026). The pictures are transparent, and every caller keeps
 * the touch target (44 dp and up) while drawing only the letters.
 */
export type BrandLogoVariant = 'header' | 'nav' | 'large';

const headerSources: number[] = [
  require('../../assets/brand/jb-mark-header-1x.png'),
  require('../../assets/brand/jb-mark-header-2x.png'),
  require('../../assets/brand/jb-mark-header-3x.png'),
];
const navSources: number[] = [
  require('../../assets/brand/jb-mark-nav-1x.png'),
  require('../../assets/brand/jb-mark-nav-2x.png'),
  require('../../assets/brand/jb-mark-nav-3x.png'),
];
const largeSource: number = require('../../assets/brand/jb-mark-1024.png');

const defaultSizes: Record<BrandLogoVariant, number> = { header: 52, nav: 54, large: 132 };

/** The 3x file is the sharpest one the generator writes; pick the one the screen can show. */
function pick(sources: number[]): number {
  const scale = Math.max(1, Math.min(3, Math.round(PixelRatio.get())));
  return sources[scale - 1];
}

export function BrandLogo({ variant = 'header', size, style, label }: {
  variant?: BrandLogoVariant;
  size?: number;
  style?: StyleProp<ImageStyle>;
  /** Only pass a label where the mark is not already read as part of a labelled button. */
  label?: string;
}) {
  const dimension = size ?? defaultSizes[variant];
  const source = variant === 'large' ? largeSource : variant === 'nav' ? pick(navSources) : pick(headerSources);
  return (
    <Image
      source={source}
      accessibilityRole={label ? 'image' : undefined}
      accessibilityLabel={label}
      accessible={Boolean(label)}
      accessibilityIgnoresInvertColors
      style={[{ width: dimension, height: dimension }, style]}
    />
  );
}

export const BRAND_LOGO_LABEL = `${BRAND_NAME} logo`;

